-- 20260915a — FR-209 / FR-174 đợt 2: bảng `wards` — 168 phường/xã/đặc khu MỚI của TP.HCM
-- (sau sắp xếp 01/07/2025) ↔ quận/huyện CŨ. Chủ dự án 15/09/2026 chốt OPEN-27 nửa sau:
-- "lấy nguồn công khai đi, bot hỏi xác nhận trước khi ghi, ... lấy tên mới cho nó dùng
-- được Nominatim".
--
-- VÌ SAO CẦN: Nominatim/OSM sau 07/2025 trả PHƯỜNG MỚI cho một tên đường
-- (`address.suburb = "Phường Tăng Nhơn Phú"`) mà KHÔNG có quận — OSM đã bỏ ranh giới
-- quận. Cột `listings.district` và mã tin (BDS-NP-Q9-…) vẫn đi theo quận CŨ (INS-12: dân
-- vẫn gọi "Quận 9"), nên cần bảng dịch phường mới → quận cũ.
--
-- NGUỒN (công khai, ghi từng dòng ở cột `nguon`):
--   · Nghị quyết 1685/NQ-UBTVQH15 (16/06/2025) — toàn văn trên xaydungchinhsach.chinhphu.vn:
--     tên đơn vị mới + các phường/xã cũ gộp vào (cột `don_vi_cu`), quận/huyện ghi trong
--     ngoặc ở các phường đánh số.
--   · Wikipedia tiếng Việt "Lịch sử hành chính Thành phố Hồ Chí Minh" (mục 2025, chép lại
--     NQ 1685 kèm "thuộc <quận/huyện>" cho TỪNG dòng) → cột `don_vi_2025`.
--   · Trang Wikipedia của từng phường mới: toạ độ tâm (infobox), mã hành chính. Với 12
--     phường thuộc TP Thủ Đức (2021–2025): quận trước 2021 lấy theo các phường CŨ gộp vào,
--     đối chiếu danh sách 13 phường "Quận 9" và 11 phường "Quận 2" trên Wikipedia; không
--     thuộc hai danh sách = quận Thủ Đức cũ (ghi ở `ghi_chu`).
--   Dữ liệu ĐỌC MÁY từ ba nguồn trên (scratchpad build-wards.py, 15/09/2026), không nhập tay.
--   Cột `nguon` viết tắt: "NQ 1685 k.<n> + wiki LSHC" = khoản n của Nghị quyết, đối chiếu trang
--   Wikipedia "Lịch sử hành chính TP.HCM".
--
-- ĐÃ ÁP LÊN PRODUCTION 15/09/2026 qua MCP: phần DDL dưới tên migration này, phần dữ liệu
-- (168 dòng insert) qua execute_sql ngay sau — nên thân migration trên DB chỉ có DDL; file này
-- là bản gốc đầy đủ.
--
-- QUY ƯỚC `quan_cu`: đúng chuỗi `bocQuan()` / mã tin đang dùng — "Quận 9", "Quận Bình
-- Thạnh", "Huyện Củ Chi"; ngoài TP.HCM cũ thì "Bình Dương", "Vũng Tàu", "Bà Rịa", "Phú Mỹ",
-- "Bà Rịa – Vũng Tàu" (khớp `vungNgoai()` / QUAN_TEN ở dia_ban.ts).
-- Phường mới gộp từ NHIỀU quận (Bình Phú: Quận 6 + một phần Quận 8…) lấy đơn vị nêu ĐẦU
-- (phần "toàn bộ"), các đơn vị còn lại ở `don_vi_2025` + `ghi_chu`.
--
-- Bảng CHỈ service_role đọc (bot tra trong chat-reply). Repo public + "view mới mặc định
-- LỘ" (alter default privileges) → revoke TRƯỚC. Web chưa cần; muốn mở thì thêm policy.
-- `xuat_schema()` không xuất DỮ LIỆU: dựng lại từ số không phải chạy thêm file này
-- (bot/README.md §Dựng lại từ số không).

create table if not exists public.wards (
  ten           text primary key,
  loai          text not null check (loai in ('phuong', 'xa', 'dac_khu')),
  ten_day_du    text not null,
  quan_cu       text not null,
  don_vi_2025   text[] not null,
  tinh_cu       text not null check (tinh_cu in ('TP.HCM', 'Bình Dương', 'Bà Rịa – Vũng Tàu')),
  don_vi_cu     text,
  lat           numeric(9, 6),
  lng           numeric(9, 6),
  ma_hanh_chinh text,
  nguon         text not null,
  ghi_chu       text,
  created_at    timestamptz not null default now()
);

comment on table  public.wards is '[RỔ HÀNG] FR-209 / FR-174 đợt 2: 168 phường/xã/đặc khu MỚI của TP.HCM (NQ 1685/NQ-UBTVQH15, 01/07/2025) ↔ quận/huyện CŨ. Bot tra phường từ tên đường qua Nominatim rồi dịch ra quận cũ ở đây; HỎI XÁC NHẬN chủ nhà rồi mới ghi listings.ward/district. Chỉ service_role đọc.';
comment on column public.wards.ten is 'Tên đơn vị mới KHÔNG tiền tố ("Tăng Nhơn Phú") — khoá tra từ Nominatim address.suburb.';
comment on column public.wards.loai is 'phuong | xa | dac_khu.';
comment on column public.wards.ten_day_du is 'Tên đủ tiền tố ("Phường Tăng Nhơn Phú") — chuỗi ghi vào listings.ward.';
comment on column public.wards.quan_cu is 'Quận/huyện CŨ dân gọi, đúng chuỗi bocQuan()/mã tin ("Quận 9"); ghi vào listings.district. Phường TP Thủ Đức lấy quận trước 2021.';
comment on column public.wards.don_vi_2025 is 'Đơn vị cấp huyện TRƯỚC 01/07/2025 theo NQ 1685 (một phường mới có thể gộp từ nhiều quận).';
comment on column public.wards.tinh_cu is 'TP.HCM | Bình Dương | Bà Rịa – Vũng Tàu (tỉnh cũ trước sáp nhập 07/2025).';
comment on column public.wards.don_vi_cu is 'Câu "trên cơ sở toàn bộ phường X, Y…" — các phường/xã cũ gộp vào (NQ 1685 qua Wikipedia Lịch sử hành chính).';
comment on column public.wards.lat is 'Vĩ độ tâm (Wikipedia infobox), có thể null.';
comment on column public.wards.lng is 'Kinh độ tâm (Wikipedia infobox), có thể null.';
comment on column public.wards.ma_hanh_chinh is 'Mã đơn vị hành chính (Wikipedia infobox), có thể null.';
comment on column public.wards.nguon is 'Nguồn công khai của dòng này.';
comment on column public.wards.ghi_chu is 'Gộp từ nhiều quận / quận trước 2021 — chỗ nào suy luận thì nói rõ ở đây.';

alter table public.wards enable row level security;
revoke all on table public.wards from public, anon, authenticated;
grant select on table public.wards to service_role;

on conflict (ten) do update set
  loai = excluded.loai, ten_day_du = excluded.ten_day_du, quan_cu = excluded.quan_cu,
  don_vi_2025 = excluded.don_vi_2025, tinh_cu = excluded.tinh_cu, don_vi_cu = excluded.don_vi_cu,
  lat = excluded.lat, lng = excluded.lng, ma_hanh_chinh = excluded.ma_hanh_chinh,
  nguon = excluded.nguon, ghi_chu = excluded.ghi_chu;
